package com.pavithran.aichat.controller; import com.pavithran.aichat.dto.*; import com.pavithran.aichat.service.ChatService; import jakarta.validation.Valid; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api") @CrossOrigin(origins="*") public class ChatController { private final ChatService chatService; public ChatController(ChatService s){chatService=s;} @GetMapping("/health") public ResponseEntity<String> health(){return ResponseEntity.ok("Pavi AI backend is running");} @PostMapping("/chat") public ChatResponse chat(@Valid @RequestBody ChatRequest r){return chatService.chat(r);} }
